import MaterialDesignIcons from "@react-native-vector-icons/material-design-icons";
import { useFocusEffect, useLocalSearchParams, useRouter } from "expo-router";
import React, { useCallback, useEffect, useMemo, useState } from "react";
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, Text, TextInput, View } from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { AdvancedOptions, EmptyState, SearchAndFilter, StickyActionBar } from "../../src/components/ProgressiveUI";
import { ACTIVITY_COLORS, ACTIVITY_ICONS, ACTIVITY_LABELS } from "../../src/training/catalog";
import { getCloudStatus, subscribeCloudStatus } from "../../src/cloud/cloudSync";
import { addDays, clonePrescription, uid } from "../../src/training/calculations";
import type { CardioBlock, ExerciseDefinition, MobilityMovementPlan, PlannedSession, StrengthExercisePlan, StrengthSetPlan, StrengthTechnique, TrainingState, WorkoutPrescription } from "../../src/training/types";
import { copyTrainingSession, getTrainingState, scheduleTrainingSession, setPlannedSessionStatus, startTrainingSession } from "../../src/store/trainingStore";
import { colors, withAlpha, radius, spacing } from "../../src/theme";
import { matchesSearch } from "../../src/utils/search";

const GROUP_TECHNIQUES: StrengthTechnique[] = ["superset", "biset", "triset", "circuit"];
const SET_TECHNIQUES: StrengthTechnique[] = ["normal", "drop_set", "strip_set", "rest_pause", "pyramid_up", "pyramid_down"];
const TECHNIQUE_LABEL: Record<StrengthTechnique, string> = { normal: "Normal", superset: "Superset", biset: "Biset", triset: "Triset", circuit: "Circuito", drop_set: "Drop set", strip_set: "Strip set", rest_pause: "Rest-pause", pyramid_up: "Pirâmide +", pyramid_down: "Pirâmide −" };
const CARDIO_KIND_LABEL: Record<string, string> = { easy: "Leve", recovery: "Regenerativa", interval: "Intervalada", tempo: "Tempo", progressive: "Progressiva", long: "Longão", custom: "Personalizada", indoor: "Indoor", road: "Rua" };
const CROSSFIT_SECTION_LABEL: Record<string, string> = { warmup: "Aquecimento", skill: "Técnica", strength: "Força", wod: "WOD", mobility: "Mobilidade", cooldown: "Volta à calma" };

export default function PlannedTrainingScreen() {
  const { plannedId } = useLocalSearchParams<{ plannedId: string }>();
  const router = useRouter(); const insets = useSafeAreaInsets();
  const [state, setState] = useState<TrainingState | null>(null);
  const [planned, setPlanned] = useState<PlannedSession | null>(null);
  const [prescription, setPrescription] = useState<WorkoutPrescription | null>(null);
  const [name, setName] = useState(""); const [time, setTime] = useState(""); const [duration, setDuration] = useState(""); const [notes, setNotes] = useState("");
  const [saving, setSaving] = useState(false); const [message, setMessage] = useState<string | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [cloudReady, setCloudReady] = useState(getCloudStatus().readyForData);
  useEffect(() => subscribeCloudStatus((next) => setCloudReady(next.readyForData)), []);

  const load = useCallback(async () => {
    if (!getCloudStatus().readyForData) return;
    try {
      const current = await getTrainingState(); const item = current.plannedSessions.find((candidate) => candidate.id === plannedId) ?? null;
      setState(current); setPlanned(item); setLoadError(null);
      if (item) { setPrescription(clonePrescription(item.prescriptionSnapshot)); setName(item.name); setTime(item.scheduledTime ?? ""); setDuration(item.estimatedDurationMinutes ? String(item.estimatedDurationMinutes) : ""); setNotes(item.notes ?? ""); }
    } catch (cause) { setLoadError(cause instanceof Error ? cause.message : "Não foi possível carregar a sessão."); }
  }, [plannedId]);
  useFocusEffect(useCallback(() => { if (cloudReady) void load(); }, [cloudReady, load]));
  const execution = state?.sessions.find((session) => session.plannedSessionId === plannedId);
  const exercises = useMemo(() => state?.exercises.filter((exercise) => !exercise.archivedAt && exercise.activityType === planned?.activityType) ?? [], [state, planned]);

  const save = async () => {
    if (!planned || !prescription) return false; setSaving(true); setMessage(null);
    try { await scheduleTrainingSession({ id: planned.id, name, activityType: planned.activityType, date: planned.date, scheduledTime: time, estimatedDurationMinutes: duration ? Number(duration) : undefined, prescription, notes }); setMessage("Planejamento salvo."); await load(); return true; }
    catch (cause) { setMessage(cause instanceof Error ? cause.message : "Não foi possível salvar."); return false; }
    finally { setSaving(false); }
  };
  const start = async () => { if (!planned || saving) return; if (!(await save())) return; setSaving(true); try { const session = await startTrainingSession(planned.id); router.replace(`/treino/${session.id}`); } catch (cause) { setMessage(cause instanceof Error ? cause.message : "Não foi possível iniciar."); } finally { setSaving(false); } };
  const setStatus = async (status: "skipped" | "canceled" | "planned") => { if (!planned) return; await setPlannedSessionStatus(planned.id, status); await load(); };
  const copyTomorrow = async () => { if (!planned) return; const copy = await copyTrainingSession(planned.id, addDays(planned.date, 1)); router.push(`/treino-planejado/${copy.id}`); };

  if (!state || !planned || !prescription) return <View style={styles.loading}>{!state && !loadError ? <ActivityIndicator color={colors.brandPrimary} /> : null}<Text style={styles.muted}>{loadError ?? (state ? "Sessão não encontrada." : "Carregando sessão…")}</Text>{loadError ? <Pressable onPress={() => void load()}><Text style={styles.addInlineText}>Tentar novamente</Text></Pressable> : null}</View>;
  const accent = ACTIVITY_COLORS[planned.activityType];
  return <ScrollView style={styles.screen} contentContainerStyle={[styles.content, { paddingTop: insets.top + spacing.lg }]} keyboardShouldPersistTaps="handled">
    <View style={styles.header}><Pressable style={styles.iconButton} onPress={() => router.back()} accessibilityLabel="Voltar"><MaterialDesignIcons name="arrow-left" size={23} color={colors.onSurface} /></Pressable><View style={[styles.activityIcon, { backgroundColor: `${accent}20` }]}><MaterialDesignIcons name={ACTIVITY_ICONS[planned.activityType] as never} size={25} color={accent} /></View><View style={{ flex: 1 }}><Text style={[styles.eyebrow, { color: accent }]}>{ACTIVITY_LABELS[planned.activityType].toUpperCase()}</Text><Text style={styles.title}>{planned.name}</Text></View></View>
    <View style={styles.notice}><MaterialDesignIcons name="shield-check-outline" size={20} color={colors.brandPrimary} /><Text style={styles.noticeText}>Planejamento e execução são separados. O histórico preserva esta prescrição mesmo se você editar o plano depois.</Text></View>
    <View style={styles.card}><Field label="Nome"><TextInput style={styles.input} value={name} onChangeText={setName} /></Field><Field label="Horário"><TextInput style={styles.input} value={time} onChangeText={setTime} placeholder="HH:MM · opcional" placeholderTextColor={colors.muted} /></Field><AdvancedOptions title="Detalhes da sessão" summary="Duração e orientações opcionais"><Field label="Duração prevista"><TextInput style={styles.input} value={duration} onChangeText={setDuration} keyboardType="numeric" placeholder="min" placeholderTextColor={colors.muted} /></Field><Field label="Orientações desta sessão"><TextInput style={[styles.input, styles.multiline]} value={notes} onChangeText={setNotes} multiline placeholder="Opcional" placeholderTextColor={colors.muted} /></Field></AdvancedOptions></View>
    <TrainingPrescriptionFields prescription={prescription} exercises={exercises} onChange={setPrescription} />
    {message ? <Text style={message.includes("salvo") ? styles.success : styles.error}>{message}</Text> : null}
    <StickyActionBar secondaryLabel="Salvar planejamento" onSecondary={() => void save()} primaryLabel={execution ? "Continuar execução" : "Iniciar esta sessão"} onPrimary={() => execution ? router.push(`/treino/${execution.id}`) : void start()} busy={saving} primaryDisabled={!execution && planned.status !== "planned"} />
    <View style={styles.utilityRow}><Pressable style={styles.utility} onPress={() => void copyTomorrow()}><MaterialDesignIcons name="content-copy" size={18} color={colors.brandSecondary} /><Text style={styles.utilityText}>Copiar para amanhã</Text></Pressable><Pressable style={styles.utility} onPress={() => router.push(`/treino-novo?date=${planned.date}&replaceId=${planned.id}`)}><MaterialDesignIcons name="swap-horizontal" size={18} color={colors.brandTertiary} /><Text style={styles.utilityText}>Substituir excepcionalmente</Text></Pressable></View>
    <View style={styles.statusRow}>{planned.status === "planned" ? <><Pressable style={styles.statusButton} onPress={() => void setStatus("skipped")}><Text style={styles.statusText}>Marcar como pulada</Text></Pressable><Pressable style={styles.statusButton} onPress={() => void setStatus("canceled")}><Text style={[styles.statusText, { color: colors.error }]}>Cancelar sessão</Text></Pressable></> : <Pressable style={styles.statusButton} onPress={() => void setStatus("planned")}><Text style={styles.statusText}>Voltar para planejada</Text></Pressable>}</View>
  </ScrollView>;
}

export function TrainingPrescriptionFields({ prescription, exercises, onChange }: { prescription: WorkoutPrescription; exercises: ExerciseDefinition[]; onChange: (value: WorkoutPrescription) => void }) {
  if (prescription.activityType === "strength") return <StrengthPlanner prescription={prescription} exercises={exercises} onChange={onChange} />;
  if (prescription.activityType === "mobility") return <MobilityPlanner prescription={prescription} exercises={exercises} onChange={onChange} />;
  if (prescription.activityType === "running" || prescription.activityType === "cycling") return <CardioPlanner activityType={prescription.activityType} prescription={prescription} onChange={onChange} />;
  if (prescription.activityType === "crossfit") return <CrossfitPlanner prescription={prescription} onChange={onChange} />;
  return <CustomPlanner prescription={prescription} onChange={onChange} />;
}

function StrengthPlanner({ prescription, exercises, onChange }: { prescription: WorkoutPrescription; exercises: ExerciseDefinition[]; onChange: (value: WorkoutPrescription) => void }) {
  const items = prescription.strength?.exercises ?? [];
  const [query, setQuery] = useState("");
  const [selectedExerciseIds, setSelectedExerciseIds] = useState<string[]>([]);
  const [editingId, setEditingId] = useState<string | null>(null);
  const available = exercises.filter((exercise) => !exercise.archivedAt && exercise.activityType === "strength" && !items.some((item) => item.exerciseId === exercise.id) && matchesSearch(query, exercise.name, exercise.primaryMuscle, exercise.equipment));
  const makeExercise = (exercise: ExerciseDefinition, order: number): StrengthExercisePlan => {
    const base = newSet();
    return { id: uid("strength-exercise"), exerciseId: exercise.id, exerciseSnapshot: { id: exercise.id, name: exercise.name, primaryMuscle: exercise.primaryMuscle, equipment: exercise.equipment, laterality: exercise.laterality, instructions: exercise.instructions }, order, sets: [base, cloneSet(base), cloneSet(base)] };
  };
  const addSelected = () => {
    const selected = available.filter((exercise) => selectedExerciseIds.includes(exercise.id));
    if (!selected.length) return;
    onChange({ ...prescription, strength: { exercises: [...items, ...selected.map((exercise, index) => makeExercise(exercise, items.length + index))] } });
    setSelectedExerciseIds([]); setQuery("");
  };
  const updateItem = (id: string, next: StrengthExercisePlan) => onChange({ ...prescription, strength: { exercises: items.map((item) => item.id === id ? next : item) } });
  const remove = (id: string) => onChange({ ...prescription, strength: { exercises: items.filter((item) => item.id !== id).map((item, order) => ({ ...item, order })) } });
  const move = (id: string, direction: -1 | 1) => {
    const ordered = items.slice().sort((a, b) => a.order - b.order);
    const index = ordered.findIndex((item) => item.id === id); const target = index + direction;
    if (index < 0 || target < 0 || target >= ordered.length) return;
    [ordered[index], ordered[target]] = [ordered[target], ordered[index]];
    onChange({ ...prescription, strength: { exercises: ordered.map((item, order) => ({ ...item, order })) } });
  };
  return <View style={styles.section}>
    <Text style={styles.sectionTitle}>EXERCÍCIOS</Text>
    <View style={styles.card}>
      <SearchAndFilter value={query} onChangeText={setQuery} placeholder="Buscar exercício, músculo ou equipamento" />
      <View style={styles.exercisePicker}>{available.slice(0, 12).map((exercise) => {
        const selected = selectedExerciseIds.includes(exercise.id);
        return <Pressable key={exercise.id} accessibilityRole="checkbox" accessibilityState={{ checked: selected }} style={[styles.exercisePickerRow, selected && styles.exercisePickerRowSelected]} onPress={() => setSelectedExerciseIds((current) => selected ? current.filter((id) => id !== exercise.id) : [...current, exercise.id])}>
          <MaterialDesignIcons name={selected ? "checkbox-marked-circle" : "checkbox-blank-circle-outline"} size={21} color={selected ? colors.brandPrimary : colors.onSurfaceTertiary} />
          <View style={{ flex: 1 }}><Text style={styles.cardTitle}>{exercise.name}</Text><Text style={styles.cardMeta}>{exercise.primaryMuscle ?? "Geral"} · {exercise.equipment ?? "Livre"}{exercise.favorite ? " · favorito" : ""}</Text></View>
        </Pressable>;
      })}</View>
      {available.length > 12 ? <Text style={styles.cardMeta}>Refine a busca para ver os demais exercícios.</Text> : null}
      <Pressable disabled={!selectedExerciseIds.length} style={[styles.addSelected, !selectedExerciseIds.length && styles.disabled]} onPress={addSelected}><Text style={styles.primaryText}>Adicionar selecionados {selectedExerciseIds.length ? `(${selectedExerciseIds.length})` : ""}</Text></Pressable>
    </View>
    {items.length ? items.slice().sort((a, b) => a.order - b.order).map((item, index) => <CompactStrengthExercise key={item.id} item={item} index={index} total={items.length} exercises={exercises} open={editingId === item.id} onToggle={() => setEditingId((current) => current === item.id ? null : item.id)} onMove={(direction) => move(item.id, direction)} onRemove={() => remove(item.id)} onChange={(next) => updateItem(item.id, next)} />) : <EmptyState icon="dumbbell" title="Nenhum exercício ainda" description="Busque e selecione um ou mais exercícios. Cada novo exercício começa com 3 séries de 8–12, 90 s e RIR 2." />}
  </View>;
}
function newSet(): StrengthSetPlan { return { id: uid("set"), kind: "working", plannedRepMin: 8, plannedRepMax: 12, loadUnit: "kg", restSeconds: 90, targetRir: 2, technique: "normal", toFailure: false }; }
function cloneSet(set: StrengthSetPlan): StrengthSetPlan { return { ...set, id: uid("set") }; }

function CompactStrengthExercise({ item, index, total, exercises, open, onToggle, onMove, onRemove, onChange }: { item: StrengthExercisePlan; index: number; total: number; exercises: ExerciseDefinition[]; open: boolean; onToggle: () => void; onMove: (direction: -1 | 1) => void; onRemove: () => void; onChange: (value: StrengthExercisePlan) => void }) {
  const first = item.sets[0] ?? newSet();
  const repSummary = first.toFailure ? "até a falha" : first.plannedReps ? `${first.plannedReps} reps` : first.plannedRepMin || first.plannedRepMax ? `${first.plannedRepMin ?? "?"}–${first.plannedRepMax ?? "?"} reps` : "repetições livres";
  const resizeSets = (count: number) => { const safe = Math.max(1, Math.min(20, count || 1)); const sets = item.sets.slice(0, safe); while (sets.length < safe) sets.push(cloneSet(sets[sets.length - 1] ?? newSet())); onChange({ ...item, sets }); };
  const applyToAll = (patch: Partial<StrengthSetPlan>) => onChange({ ...item, sets: item.sets.map((set) => ({ ...set, ...patch })) });
  const setMode = (mode: "fixed" | "range" | "failure" | "free") => applyToAll(mode === "fixed" ? { plannedReps: first.plannedReps ?? 10, plannedRepMin: undefined, plannedRepMax: undefined, toFailure: false } : mode === "range" ? { plannedReps: undefined, plannedRepMin: first.plannedRepMin ?? 8, plannedRepMax: first.plannedRepMax ?? 12, toFailure: false } : mode === "failure" ? { plannedReps: undefined, plannedRepMin: undefined, plannedRepMax: undefined, toFailure: true } : { plannedReps: undefined, plannedRepMin: undefined, plannedRepMax: undefined, toFailure: false });
  const mode = first.toFailure ? "failure" : first.plannedReps ? "fixed" : first.plannedRepMin || first.plannedRepMax ? "range" : "free";
  return <View style={styles.card} testID="compact-exercise-card">
    <Pressable accessibilityRole="button" accessibilityState={{ expanded: open }} onPress={onToggle} style={styles.compactExerciseHeader}>
      <View style={styles.orderBadge}><Text style={styles.orderBadgeText}>{index + 1}</Text></View>
      <View style={{ flex: 1 }}><Text style={styles.cardTitle}>{item.exerciseSnapshot.name}</Text><Text style={styles.compactSummary}>{item.sets.length} séries · {repSummary} · {first.restSeconds ?? 0} s{first.targetRir !== undefined ? ` · RIR ${first.targetRir}` : ""}</Text></View>
      <MaterialDesignIcons name={open ? "chevron-up" : "pencil-outline"} size={20} color={colors.brandPrimary} />
    </Pressable>
    {open ? <View style={styles.compactEditor}>
      <View style={styles.row}><Mini label="Séries"><TextInput accessibilityLabel="Quantidade de séries" style={styles.miniInput} value={String(item.sets.length)} onChangeText={(value) => resizeSets(Number(value))} keyboardType="numeric" /></Mini><Mini label="Descanso (s)"><TextInput style={styles.miniInput} value={first.restSeconds ? String(first.restSeconds) : ""} onChangeText={(value) => applyToAll({ restSeconds: Number(value) || undefined })} keyboardType="numeric" /></Mini><Mini label="RIR"><TextInput style={styles.miniInput} value={first.targetRir !== undefined ? String(first.targetRir) : ""} onChangeText={(value) => applyToAll({ targetRir: value ? Number(value) : undefined })} keyboardType="numeric" /></Mini></View>
      <Text style={styles.fieldLabel}>Como medir esta série?</Text><View style={styles.chips}><Choice label="Fixa" active={mode === "fixed"} onPress={() => setMode("fixed")} /><Choice label="Faixa" active={mode === "range"} onPress={() => setMode("range")} /><Choice label="Até a falha" active={mode === "failure"} onPress={() => setMode("failure")} /><Choice label="Livre" active={mode === "free"} onPress={() => setMode("free")} /></View>
      {mode === "fixed" ? <Mini label="Repetições"><TextInput style={styles.miniInput} value={first.plannedReps ? String(first.plannedReps) : ""} onChangeText={(value) => applyToAll({ plannedReps: Number(value) || undefined })} keyboardType="numeric" /></Mini> : null}
      {mode === "range" ? <View style={styles.row}><Mini label="Mínimo"><TextInput style={styles.miniInput} value={first.plannedRepMin ? String(first.plannedRepMin) : ""} onChangeText={(value) => applyToAll({ plannedRepMin: Number(value) || undefined })} keyboardType="numeric" /></Mini><Mini label="Máximo"><TextInput style={styles.miniInput} value={first.plannedRepMax ? String(first.plannedRepMax) : ""} onChangeText={(value) => applyToAll({ plannedRepMax: Number(value) || undefined })} keyboardType="numeric" /></Mini></View> : null}
      <Field label="Orientação específica deste exercício"><TextInput style={styles.input} value={item.planNotes ?? item.executionNotes ?? ""} onChangeText={(value) => onChange({ ...item, planNotes: value || undefined, executionNotes: undefined })} placeholder="Ex.: não chegar à falha hoje" placeholderTextColor={colors.muted} /></Field>
      {item.exerciseSnapshot.instructions ? <View style={styles.generalGuidance}><MaterialDesignIcons name="information-outline" size={18} color={colors.info} /><Text style={styles.cardMeta}>Orientação geral: {item.exerciseSnapshot.instructions}</Text></View> : null}
      <AdvancedOptions summary="Carga-alvo, agrupamento, técnica, alternativa e séries individuais">
        <Field label="Agrupamento entre exercícios"><View style={styles.chips}><Choice active={!item.groupTechnique} label="Sem grupo" onPress={() => onChange({ ...item, groupTechnique: undefined, groupId: undefined })} />{GROUP_TECHNIQUES.map((technique) => <Choice key={technique} active={item.groupTechnique === technique} label={TECHNIQUE_LABEL[technique]} onPress={() => onChange({ ...item, groupTechnique: technique, groupId: item.groupId ?? "A" })} />)}</View></Field>
        {item.groupTechnique ? <Field label="Identificador do grupo"><TextInput style={styles.input} value={item.groupId ?? ""} onChangeText={(groupId) => onChange({ ...item, groupId: groupId || undefined })} placeholder="Ex.: A" placeholderTextColor={colors.muted} /></Field> : null}
        <Field label="Alternativa se faltar equipamento"><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.catalog}><Choice active={!item.alternativeExerciseId} label="Nenhuma" onPress={() => onChange({ ...item, alternativeExerciseId: undefined })} />{exercises.filter((exercise) => exercise.id !== item.exerciseId).slice(0, 18).map((exercise) => <Choice key={exercise.id} active={item.alternativeExerciseId === exercise.id} label={exercise.name} onPress={() => onChange({ ...item, alternativeExerciseId: exercise.id })} />)}</ScrollView></Field>
        <Text style={styles.fieldLabel}>Personalizar séries</Text>{item.sets.map((set, setIndex) => <StrengthSetEditor key={set.id} set={set} index={setIndex} onChange={(next) => onChange({ ...item, sets: item.sets.map((candidate) => candidate.id === next.id ? next : candidate) })} onRemove={() => onChange({ ...item, sets: item.sets.length > 1 ? item.sets.filter((candidate) => candidate.id !== set.id) : item.sets })} />)}
      </AdvancedOptions>
      <View style={styles.compactActions}><Pressable style={styles.smallAction} disabled={index === 0} onPress={() => onMove(-1)}><MaterialDesignIcons name="arrow-up" size={18} color={index === 0 ? colors.muted : colors.onSurfaceSecondary} /><Text style={styles.smallActionText}>Subir</Text></Pressable><Pressable style={styles.smallAction} disabled={index === total - 1} onPress={() => onMove(1)}><MaterialDesignIcons name="arrow-down" size={18} color={index === total - 1 ? colors.muted : colors.onSurfaceSecondary} /><Text style={styles.smallActionText}>Descer</Text></Pressable><Pressable style={styles.smallAction} onPress={() => onChange({ ...item, sets: [...item.sets, cloneSet(item.sets[item.sets.length - 1] ?? newSet())] })}><MaterialDesignIcons name="content-copy" size={18} color={colors.onSurfaceSecondary} /><Text style={styles.smallActionText}>Duplicar série</Text></Pressable><Pressable style={styles.smallAction} onPress={onRemove}><MaterialDesignIcons name="trash-can-outline" size={18} color={colors.error} /><Text style={[styles.smallActionText, { color: colors.error }]}>Remover</Text></Pressable></View>
    </View> : null}
  </View>;
}

function StrengthSetEditor({ set, index, onChange, onRemove }: { set: StrengthSetPlan; index: number; onChange: (value: StrengthSetPlan) => void; onRemove: () => void }) { const number = (value: string) => value ? Number(value) : undefined; return <View style={styles.compactSetRow}><Text style={styles.setNumber}>{index + 1}</Text><Mini label="Carga"><TextInput style={styles.miniInput} value={set.plannedLoad ? String(set.plannedLoad) : ""} onChangeText={(v) => onChange({ ...set, plannedLoad: number(v) })} keyboardType="decimal-pad" placeholder="—" placeholderTextColor={colors.muted} /></Mini><Mini label="RPE"><TextInput style={styles.miniInput} value={set.targetRpe !== undefined ? String(set.targetRpe) : ""} onChangeText={(v) => onChange({ ...set, targetRpe: number(v) })} keyboardType="numeric" placeholder="—" placeholderTextColor={colors.muted} /></Mini><View style={{ flex: 2 }}><Text style={styles.miniLabel}>Tipo / técnica</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.catalog}><Choice active={set.kind === "warmup"} label="Aquecimento" onPress={() => onChange({ ...set, kind: "warmup" })} /><Choice active={set.kind === "preparatory"} label="Preparatória" onPress={() => onChange({ ...set, kind: "preparatory" })} /><Choice active={set.kind === "working"} label="Válida" onPress={() => onChange({ ...set, kind: "working" })} />{SET_TECHNIQUES.filter((technique) => technique !== "normal").map((technique) => <Choice key={technique} active={set.technique === technique} label={TECHNIQUE_LABEL[technique]} onPress={() => onChange({ ...set, technique })} />)}</ScrollView></View><Pressable accessibilityLabel={`Remover série ${index + 1}`} onPress={onRemove}><MaterialDesignIcons name="close" size={18} color={colors.onSurfaceTertiary} /></Pressable></View>; }

function MobilityPlanner({ prescription, exercises, onChange }: { prescription: WorkoutPrescription; exercises: ExerciseDefinition[]; onChange: (value: WorkoutPrescription) => void }) {
  const movements = prescription.mobility?.movements ?? [];
  const update = (values: MobilityMovementPlan[], plannedTotalMinutes = prescription.mobility?.plannedTotalMinutes) => onChange({ ...prescription, mobility: { movements: values, plannedTotalMinutes } });
  const patch = (id: string, values: Partial<MobilityMovementPlan>) => update(movements.map((item) => item.id === id ? { ...item, ...values } : item));
  const add = (exercise: ExerciseDefinition) => update([...movements, { id: uid("movement"), exerciseId: exercise.id, name: exercise.name, bodyRegion: exercise.primaryMuscle, durationSeconds: 30, sets: 1, sides: exercise.laterality === "unilateral" ? "both" : "not_applicable", instructions: exercise.instructions, order: movements.length }]);
  const move = (id: string, direction: -1 | 1) => { const ordered = movements.slice().sort((a, b) => a.order - b.order); const index = ordered.findIndex((item) => item.id === id); const target = index + direction; if (index < 0 || target < 0 || target >= ordered.length) return; [ordered[index], ordered[target]] = [ordered[target], ordered[index]]; update(ordered.map((item, order) => ({ ...item, order }))); };
  return <View style={styles.section}><Text style={styles.sectionTitle}>MOVIMENTOS</Text><View style={styles.card}><Field label="Tempo total previsto (min)"><TextInput style={styles.input} value={prescription.mobility?.plannedTotalMinutes ? String(prescription.mobility.plannedTotalMinutes) : ""} onChangeText={(value) => update(movements, Number(value) || undefined)} keyboardType="numeric" placeholder="Opcional" placeholderTextColor={colors.muted} /></Field></View><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.catalog}>{exercises.map((exercise) => <Pressable key={exercise.id} style={styles.catalogItem} onPress={() => add(exercise)}><MaterialDesignIcons name="plus-circle-outline" size={18} color={colors.brandPrimary} /><Text style={styles.catalogText}>{exercise.name}</Text></Pressable>)}</ScrollView>{movements.slice().sort((a, b) => a.order - b.order).map((movement, index) => <View key={movement.id} style={styles.card}><View style={styles.cardHeader}><View style={{ flex: 1 }}><Text style={styles.cardTitle}>{movement.name}</Text><Text style={styles.cardMeta}>{movement.bodyRegion || "Região não informada"}</Text></View><Pressable style={styles.smallIcon} onPress={() => move(movement.id, -1)} disabled={index === 0}><MaterialDesignIcons name="arrow-up" size={18} color={index === 0 ? colors.muted : colors.onSurfaceSecondary} /></Pressable><Pressable style={styles.smallIcon} onPress={() => move(movement.id, 1)} disabled={index === movements.length - 1}><MaterialDesignIcons name="arrow-down" size={18} color={index === movements.length - 1 ? colors.muted : colors.onSurfaceSecondary} /></Pressable><Pressable style={styles.smallIcon} onPress={() => update(movements.filter((item) => item.id !== movement.id))}><MaterialDesignIcons name="trash-can-outline" size={19} color={colors.error} /></Pressable></View><Field label="Região corporal"><TextInput style={styles.input} value={movement.bodyRegion ?? ""} onChangeText={(bodyRegion) => patch(movement.id, { bodyRegion: bodyRegion || undefined })} placeholder="Ex.: quadril" placeholderTextColor={colors.muted} /></Field><View style={styles.three}><Mini label="Segundos"><TextInput style={styles.miniInput} value={movement.durationSeconds ? String(movement.durationSeconds) : ""} onChangeText={(v) => patch(movement.id, { durationSeconds: Number(v) || undefined })} keyboardType="numeric" /></Mini><Mini label="Séries"><TextInput style={styles.miniInput} value={movement.sets ? String(movement.sets) : ""} onChangeText={(v) => patch(movement.id, { sets: Number(v) || undefined })} keyboardType="numeric" /></Mini><Mini label="Repetições"><TextInput style={styles.miniInput} value={movement.repetitions ? String(movement.repetitions) : ""} onChangeText={(v) => patch(movement.id, { repetitions: Number(v) || undefined })} keyboardType="numeric" /></Mini></View><View style={styles.chips}>{(["both", "right", "left", "not_applicable"] as const).map((side) => <Choice key={side} active={movement.sides === side} label={side === "both" ? "Dois lados" : side === "right" ? "Direito" : side === "left" ? "Esquerdo" : "Sem lado"} onPress={() => patch(movement.id, { sides: side })} />)}</View><Field label="Orientações"><TextInput style={[styles.input, styles.multiline]} value={movement.instructions ?? ""} onChangeText={(instructions) => patch(movement.id, { instructions: instructions || undefined })} multiline placeholder="Como executar" placeholderTextColor={colors.muted} /></Field><Field label="Observações"><TextInput style={styles.input} value={movement.notes ?? ""} onChangeText={(notes) => patch(movement.id, { notes: notes || undefined })} placeholder="Opcional" placeholderTextColor={colors.muted} /></Field></View>)}{!movements.length ? <Empty text="Adicione movimentos e marque cada um separadamente durante a execução." /> : null}</View>;
}

function CardioPlanner({ activityType, prescription, onChange }: { activityType: "running" | "cycling"; prescription: WorkoutPrescription; onChange: (value: WorkoutPrescription) => void }) {
  const data = activityType === "running" ? prescription.running! : prescription.cycling!; const blocks = data.blocks;
  const setData = (updates: Record<string, unknown>) => onChange(activityType === "running" ? { ...prescription, running: { ...prescription.running!, ...updates } } : { ...prescription, cycling: { ...prescription.cycling!, ...updates } });
  const patchBlock = (id: string, updates: Partial<CardioBlock>) => setData({ blocks: blocks.map((item) => item.id === id ? { ...item, ...updates } : item) });
  const addBlock = () => setData({ blocks: [...blocks, { id: uid("cardio-block"), phase: blocks.length ? "work" : "warmup", name: blocks.length ? "Bloco de trabalho" : "Aquecimento", order: blocks.length } as CardioBlock] });
  return <View style={styles.section}><Text style={styles.sectionTitle}>{activityType === "running" ? "CORRIDA" : "BIKE"} · PLANEJAMENTO</Text><View style={styles.card}><View style={styles.row}><Mini label="Distância (km)"><TextInput style={styles.miniInput} value={data.plannedDistanceKm ? String(data.plannedDistanceKm) : ""} onChangeText={(v) => setData({ plannedDistanceKm: Number(v) || undefined })} keyboardType="decimal-pad" /></Mini><Mini label="Duração (min)"><TextInput style={styles.miniInput} value={data.plannedDurationMinutes ? String(data.plannedDurationMinutes) : ""} onChangeText={(v) => setData({ plannedDurationMinutes: Number(v) || undefined })} keyboardType="numeric" /></Mini></View><View style={styles.chips}>{(activityType === "running" ? ["easy", "recovery", "interval", "tempo", "progressive", "long", "custom"] : ["indoor", "road", "recovery", "interval", "custom"]).map((kind) => <Choice key={kind} active={data.kind === kind} label={CARDIO_KIND_LABEL[kind]} onPress={() => setData({ kind })} />)}</View>{activityType === "running" ? <><Text style={styles.fieldLabel}>Local</Text><View style={styles.chips}>{(["street", "track", "treadmill"] as const).map((location) => <Choice key={location} active={prescription.running?.location === location} label={location === "street" ? "Rua" : location === "track" ? "Pista" : "Esteira"} onPress={() => setData({ location })} />)}</View><View style={styles.row}><Field label="Inclinação da esteira (%)" grow><TextInput style={styles.input} value={prescription.running?.inclinePercent !== undefined ? String(prescription.running.inclinePercent) : ""} onChangeText={(value) => setData({ inclinePercent: Number(value) || undefined })} keyboardType="decimal-pad" placeholder="Opcional" placeholderTextColor={colors.muted} /></Field></View><Field label="Aquecimento"><TextInput style={styles.input} value={prescription.running?.warmup ?? ""} onChangeText={(warmup) => setData({ warmup: warmup || undefined })} placeholder="Opcional" placeholderTextColor={colors.muted} /></Field><Field label="Volta à calma"><TextInput style={styles.input} value={prescription.running?.cooldown ?? ""} onChangeText={(cooldown) => setData({ cooldown: cooldown || undefined })} placeholder="Opcional" placeholderTextColor={colors.muted} /></Field></> : <Field label="Resistência da bike indoor"><TextInput style={styles.input} value={prescription.cycling?.resistanceLevel !== undefined ? String(prescription.cycling.resistanceLevel) : ""} onChangeText={(value) => setData({ resistanceLevel: Number(value) || undefined })} keyboardType="decimal-pad" placeholder="Opcional" placeholderTextColor={colors.muted} /></Field>}</View>{blocks.map((block, index) => <View key={block.id} style={styles.setCard}><View style={styles.cardHeader}><Text style={styles.setTitle}>BLOCO {index + 1}</Text><Pressable onPress={() => setData({ blocks: blocks.filter((item) => item.id !== block.id) })}><MaterialDesignIcons name="close" size={18} color={colors.onSurfaceTertiary} /></Pressable></View><TextInput style={styles.input} value={block.name} onChangeText={(name) => patchBlock(block.id, { name })} /><View style={styles.chips}>{(["warmup", "work", "recovery", "cooldown", "custom"] as const).map((phase) => <Choice key={phase} active={block.phase === phase} label={phase === "warmup" ? "Aquecimento" : phase === "work" ? "Trabalho" : phase === "recovery" ? "Recuperação" : phase === "cooldown" ? "Volta à calma" : "Personalizado"} onPress={() => patchBlock(block.id, { phase })} />)}</View><View style={styles.three}><Mini label="Repetições"><TextInput style={styles.miniInput} value={block.repetitions ? String(block.repetitions) : ""} onChangeText={(v) => patchBlock(block.id, { repetitions: Number(v) || undefined })} keyboardType="numeric" /></Mini><Mini label="Segundos"><TextInput style={styles.miniInput} value={block.durationSeconds ? String(block.durationSeconds) : ""} onChangeText={(v) => patchBlock(block.id, { durationSeconds: Number(v) || undefined })} keyboardType="numeric" /></Mini><Mini label="Distância km"><TextInput style={styles.miniInput} value={block.distanceKm ? String(block.distanceKm) : ""} onChangeText={(v) => patchBlock(block.id, { distanceKm: Number(v) || undefined })} keyboardType="decimal-pad" /></Mini></View><View style={styles.three}>{activityType === "running" ? <><Mini label="Ritmo alvo s/km"><TextInput style={styles.miniInput} value={block.targetPaceSecondsPerKm ? String(block.targetPaceSecondsPerKm) : ""} onChangeText={(v) => patchBlock(block.id, { targetPaceSecondsPerKm: Number(v) || undefined })} keyboardType="numeric" /></Mini><Mini label="Velocidade km/h"><TextInput style={styles.miniInput} value={block.targetSpeedKmh ? String(block.targetSpeedKmh) : ""} onChangeText={(v) => patchBlock(block.id, { targetSpeedKmh: Number(v) || undefined })} keyboardType="decimal-pad" /></Mini><Mini label="Inclinação %"><TextInput style={styles.miniInput} value={block.targetInclinePercent ? String(block.targetInclinePercent) : ""} onChangeText={(v) => patchBlock(block.id, { targetInclinePercent: Number(v) || undefined })} keyboardType="decimal-pad" /></Mini></> : <><Mini label="Cadência rpm"><TextInput style={styles.miniInput} value={block.targetCadenceRpm ? String(block.targetCadenceRpm) : ""} onChangeText={(v) => patchBlock(block.id, { targetCadenceRpm: Number(v) || undefined })} keyboardType="numeric" /></Mini><Mini label="Potência W"><TextInput style={styles.miniInput} value={block.targetPowerWatts ? String(block.targetPowerWatts) : ""} onChangeText={(v) => patchBlock(block.id, { targetPowerWatts: Number(v) || undefined })} keyboardType="numeric" /></Mini></>}</View><Field label="Observações do bloco"><TextInput style={styles.input} value={block.notes ?? ""} onChangeText={(notes) => patchBlock(block.id, { notes: notes || undefined })} placeholder="Opcional" placeholderTextColor={colors.muted} /></Field></View>)}<Pressable style={styles.addInline} onPress={addBlock}><MaterialDesignIcons name="plus" size={18} color={colors.brandPrimary} /><Text style={styles.addInlineText}>Adicionar bloco intervalado</Text></Pressable></View>;
}

function CrossfitPlanner({ prescription, onChange }: { prescription: WorkoutPrescription; onChange: (value: WorkoutPrescription) => void }) {
  const crossfit = prescription.crossfit ?? { blocks: [] }; const blocks = crossfit.blocks;
  const setCrossfit = (updates: Partial<typeof crossfit>) => onChange({ ...prescription, crossfit: { ...crossfit, ...updates } });
  const update = (next: typeof blocks) => setCrossfit({ blocks: next });
  const patchBlock = (id: string, values: Partial<typeof blocks[number]>) => update(blocks.map((item) => item.id === id ? { ...item, ...values } : item));
  const add = (section: typeof blocks[number]["section"]) => update([...blocks, { id: uid("crossfit-block"), section, name: section === "wod" ? "WOD" : section === "skill" ? "Técnica / habilidade" : section === "strength" ? "Força" : section === "cooldown" ? "Volta à calma" : section === "mobility" ? "Mobilidade" : "Aquecimento", format: section === "wod" ? "amrap" : undefined, movements: [], order: blocks.length }]);
  const addMovement = (blockId: string) => { const block = blocks.find((item) => item.id === blockId); if (!block) return; patchBlock(blockId, { movements: [...block.movements, { id: uid("crossfit-movement"), name: "Novo movimento", loadUnit: "kg", order: block.movements.length }] }); };
  return <View style={styles.section}><Text style={styles.sectionTitle}>BLOCOS DO CROSSFIT</Text><View style={styles.card}><Text style={styles.fieldLabel}>Escala planejada</Text><View style={styles.chips}>{(["rx", "scaled", "custom"] as const).map((scale) => <Choice key={scale} active={crossfit.scale === scale} label={scale.toUpperCase()} onPress={() => setCrossfit({ scale })} />)}</View>{crossfit.scale === "custom" ? <TextInput style={styles.input} value={crossfit.customScale ?? ""} onChangeText={(customScale) => setCrossfit({ customScale: customScale || undefined })} placeholder="Descreva a escala" placeholderTextColor={colors.muted} /> : null}</View><View style={styles.chips}>{(["warmup", "skill", "strength", "wod", "mobility", "cooldown"] as const).map((section) => <Choice key={section} label={`+ ${CROSSFIT_SECTION_LABEL[section]}`} onPress={() => add(section)} />)}</View>{blocks.map((block, index) => <View key={block.id} style={styles.card}><View style={styles.cardHeader}><Text style={styles.cardTitle}>{index + 1}. {block.name}</Text><Pressable onPress={() => update(blocks.filter((item) => item.id !== block.id))}><MaterialDesignIcons name="trash-can-outline" size={19} color={colors.error} /></Pressable></View><TextInput style={styles.input} value={block.name} onChangeText={(name) => patchBlock(block.id, { name })} />{block.section === "wod" ? <><View style={styles.chips}>{(["amrap", "emom", "for_time", "rounds_for_time", "tabata", "chipper", "circuit"] as const).map((format) => <Choice key={format} active={block.format === format} label={format.replaceAll("_", " ")} onPress={() => patchBlock(block.id, { format })} />)}</View><View style={styles.three}><Mini label="Rounds"><TextInput style={styles.miniInput} value={block.rounds ? String(block.rounds) : ""} onChangeText={(v) => patchBlock(block.id, { rounds: Number(v) || undefined })} keyboardType="numeric" /></Mini><Mini label="Time cap (min)"><TextInput style={styles.miniInput} value={block.timeCapMinutes ? String(block.timeCapMinutes) : ""} onChangeText={(v) => patchBlock(block.id, { timeCapMinutes: Number(v) || undefined })} keyboardType="numeric" /></Mini><Mini label="Trabalho (s)"><TextInput style={styles.miniInput} value={block.workSeconds ? String(block.workSeconds) : ""} onChangeText={(v) => patchBlock(block.id, { workSeconds: Number(v) || undefined })} keyboardType="numeric" /></Mini></View><View style={styles.row}><Mini label="Descanso (s)"><TextInput style={styles.miniInput} value={block.restSeconds ? String(block.restSeconds) : ""} onChangeText={(v) => patchBlock(block.id, { restSeconds: Number(v) || undefined })} keyboardType="numeric" /></Mini></View></> : null}<Text style={styles.fieldLabel}>Movimentos</Text>{block.movements.map((movement, movementIndex) => <View key={movement.id} style={styles.setCard}><View style={styles.row}><TextInput style={[styles.input, { flex: 1 }]} value={movement.name} onChangeText={(name) => patchBlock(block.id, { movements: block.movements.map((item) => item.id === movement.id ? { ...item, name } : item) })} placeholder={`Movimento ${movementIndex + 1}`} placeholderTextColor={colors.muted} /><Pressable style={styles.smallIcon} onPress={() => patchBlock(block.id, { movements: block.movements.filter((item) => item.id !== movement.id) })}><MaterialDesignIcons name="close" size={18} color={colors.error} /></Pressable></View><View style={styles.three}><Mini label="Repetições"><TextInput style={styles.miniInput} value={movement.repetitions ? String(movement.repetitions) : ""} onChangeText={(value) => patchBlock(block.id, { movements: block.movements.map((item) => item.id === movement.id ? { ...item, repetitions: Number(value) || undefined } : item) })} keyboardType="numeric" /></Mini><Mini label={`Carga (${movement.loadUnit ?? "kg"})`}><TextInput style={styles.miniInput} value={movement.load ? String(movement.load) : ""} onChangeText={(value) => patchBlock(block.id, { movements: block.movements.map((item) => item.id === movement.id ? { ...item, load: Number(value) || undefined } : item) })} keyboardType="decimal-pad" /></Mini></View><View style={styles.chips}><Choice active={movement.loadUnit === "kg"} label="kg" onPress={() => patchBlock(block.id, { movements: block.movements.map((item) => item.id === movement.id ? { ...item, loadUnit: "kg" } : item) })} /><Choice active={movement.loadUnit === "lb"} label="lb" onPress={() => patchBlock(block.id, { movements: block.movements.map((item) => item.id === movement.id ? { ...item, loadUnit: "lb" } : item) })} /></View></View>)}<Pressable style={styles.addInline} onPress={() => addMovement(block.id)}><MaterialDesignIcons name="plus" size={18} color={colors.brandPrimary} /><Text style={styles.addInlineText}>Adicionar movimento</Text></Pressable><Field label="Observações do bloco"><TextInput style={[styles.input, styles.multiline]} value={block.notes ?? ""} onChangeText={(notes) => patchBlock(block.id, { notes: notes || undefined })} multiline placeholder="Orientações, estratégia ou detalhes" placeholderTextColor={colors.muted} /></Field></View>)}{!blocks.length ? <Empty text="Monte aquecimento, habilidade, força, WOD, mobilidade e volta à calma como blocos independentes." /> : null}</View>;
}

function CustomPlanner({ prescription, onChange }: { prescription: WorkoutPrescription; onChange: (value: WorkoutPrescription) => void }) { const fields = prescription.custom?.fields ?? []; return <View style={styles.section}><Text style={styles.sectionTitle}>CAMPOS PERSONALIZADOS</Text>{fields.map((field) => <View key={field.id} style={styles.row}><TextInput style={[styles.input, { flex: 1 }]} value={field.label} onChangeText={(label) => onChange({ ...prescription, custom: { fields: fields.map((item) => item.id === field.id ? { ...item, label } : item) } })} placeholder="Nome do campo" placeholderTextColor={colors.muted} /><Pressable style={styles.smallIcon} onPress={() => onChange({ ...prescription, custom: { fields: fields.filter((item) => item.id !== field.id) } })}><MaterialDesignIcons name="close" size={18} color={colors.error} /></Pressable></View>)}<Pressable style={styles.addInline} onPress={() => onChange({ ...prescription, custom: { fields: [...fields, { id: uid("custom-field"), label: "Novo campo", value: "" }] } })}><MaterialDesignIcons name="plus" size={18} color={colors.brandPrimary} /><Text style={styles.addInlineText}>Adicionar campo</Text></Pressable></View>; }

function Field({ label, children, grow }: { label: string; children: React.ReactNode; grow?: boolean }) { return <View style={grow ? { flex: 1 } : undefined}><Text style={styles.fieldLabel}>{label}</Text>{children}</View>; }
function Mini({ label, children }: { label: string; children: React.ReactNode }) { return <View style={{ flex: 1 }}><Text style={styles.miniLabel}>{label}</Text>{children}</View>; }
function Choice({ label, active, onPress }: { label: string; active?: boolean; onPress: () => void }) { return <Pressable style={[styles.choice, active && styles.choiceActive]} onPress={onPress}><Text style={[styles.choiceText, active && styles.choiceTextActive]}>{label}</Text></Pressable>; }
function Empty({ text }: { text: string }) { return <View style={styles.empty}><MaterialDesignIcons name="playlist-plus" size={28} color={colors.onSurfaceTertiary} /><Text style={styles.muted}>{text}</Text></View>; }

